cases.bad:
// background broadcasts to all listeners, no tab scoping
chrome.runtime.sendMessage({ type: 'DETECTED_MEDIA_UPDATE', media });
// popup renders whatever arrives — leaks media from other tabs

cases.good:
// payload carries tabId, popup filters
chrome.runtime.sendMessage({ type: 'DETECTED_MEDIA_UPDATE', tabId, media });
// popup: if (payload.tabId !== tabIdRef.current) return;

// no fallback — empty means empty
const media = tabMedia[tabId] ?? [];
return { success: false, error: 'No media found for this tab' };
